PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS addresses(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,color TEXT NOT NULL DEFAULT '#8272d5',enabled INTEGER NOT NULL DEFAULT 1,send_enabled INTEGER NOT NULL DEFAULT 1,signature TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,address_id TEXT NOT NULL REFERENCES addresses(id),thread_id TEXT NOT NULL,folder TEXT NOT NULL CHECK(folder IN('inbox','archive','sent','draft','spam','trash')),direction TEXT NOT NULL,subject TEXT NOT NULL,from_address TEXT NOT NULL,from_name TEXT NOT NULL DEFAULT '',to_json TEXT NOT NULL DEFAULT '[]',cc_json TEXT NOT NULL DEFAULT '[]',bcc_json TEXT NOT NULL DEFAULT '[]',snippet TEXT NOT NULL DEFAULT '',received_at TEXT NOT NULL,is_read INTEGER NOT NULL DEFAULT 0,starred INTEGER NOT NULL DEFAULT 0,labels_json TEXT NOT NULL DEFAULT '[]',size INTEGER NOT NULL DEFAULT 0,rfc_id TEXT NOT NULL DEFAULT '',provider_id TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'received',error TEXT NOT NULL DEFAULT '',body_key TEXT NOT NULL DEFAULT '',raw_key TEXT NOT NULL DEFAULT '',search_text TEXT NOT NULL DEFAULT '',delivery_key TEXT UNIQUE,previous_folder TEXT,reply_id TEXT,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS messages_mailbox_date ON messages(address_id,folder,received_at DESC);
CREATE INDEX IF NOT EXISTS messages_thread ON messages(address_id,thread_id,received_at);
CREATE INDEX IF NOT EXISTS messages_rfc ON messages(address_id,rfc_id);
CREATE VIRTUAL TABLE IF NOT EXISTS messages_fts USING fts5(subject,from_address,search_text,content='messages',content_rowid='rowid',tokenize='unicode61');
CREATE TRIGGER IF NOT EXISTS messages_ai AFTER INSERT ON messages BEGIN INSERT INTO messages_fts(rowid,subject,from_address,search_text) VALUES(new.rowid,new.subject,new.from_address,new.search_text); END;
CREATE TRIGGER IF NOT EXISTS messages_ad AFTER DELETE ON messages BEGIN INSERT INTO messages_fts(messages_fts,rowid,subject,from_address,search_text) VALUES('delete',old.rowid,old.subject,old.from_address,old.search_text); END;
CREATE TRIGGER IF NOT EXISTS messages_au AFTER UPDATE OF subject,from_address,search_text ON messages BEGIN INSERT INTO messages_fts(messages_fts,rowid,subject,from_address,search_text) VALUES('delete',old.rowid,old.subject,old.from_address,old.search_text); INSERT INTO messages_fts(rowid,subject,from_address,search_text) VALUES(new.rowid,new.subject,new.from_address,new.search_text); END;
CREATE TABLE IF NOT EXISTS attachments(id TEXT PRIMARY KEY,message_id TEXT REFERENCES messages(id) ON DELETE CASCADE,address_id TEXT NOT NULL REFERENCES addresses(id),filename TEXT NOT NULL,type TEXT NOT NULL,size INTEGER NOT NULL,object_key TEXT NOT NULL,content_id TEXT NOT NULL DEFAULT '',disposition TEXT NOT NULL DEFAULT 'attachment',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS intakes(id TEXT PRIMARY KEY,address_id TEXT NOT NULL,raw_key TEXT NOT NULL,from_address TEXT NOT NULL,to_address TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL,error TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,message_id TEXT NOT NULL UNIQUE REFERENCES messages(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'queued',due_at TEXT NOT NULL,claimed_at TEXT,attempts INTEGER NOT NULL DEFAULT 0,payload_key TEXT NOT NULL,created_at TEXT NOT NULL,error TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS contacts(email TEXT PRIMARY KEY COLLATE NOCASE,name TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS labels(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,color TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rules(id TEXT PRIMARY KEY,field TEXT NOT NULL,operator TEXT NOT NULL,value TEXT NOT NULL,action TEXT NOT NULL,action_value TEXT NOT NULL DEFAULT '',enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS send_quota(bucket TEXT PRIMARY KEY,count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS delivery_events(id TEXT PRIMARY KEY,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
